#ifndef STUDIO_ENGINE_NAME_LINK_HPP
#define STUDIO_ENGINE_NAME_LINK_HPP
// Structure-to-name linkage.
//
// A "systematic name" caption generated by 结构转命名 is bound to the structure
// it was computed from. The binding is stored on the TEXT object as two
// document extensions (so it survives native save/reload and the CDXML
// round-trip):
//
//   studio.nameLink.digest : a decimal FNV-1a digest of the structure graph the
//                            caption was generated for (topology, element,
//                            label, charge, isotope, hydrogen count, bond
//                            order/display/semantics and the RELATIVE geometry
//                            of the linked atoms).
//   studio.nameLink.refs   : the linked object refs, encoded by encodeRefs().
//
// Relative geometry is included so an atom drag marks the name stale, while
// moving the whole group (which translates every linked atom by the same
// delta) leaves the digest unchanged. Moving or editing the STRUCTURE is what
// the red frame reports; moving the pair together is not a structural change.
#include "next/core/document.hpp"
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <map>
#include <set>
#include <string>
#include <vector>

namespace namelink {
using namespace r62::core;

// Keys live on the naming TEXT object. "studio.nameLink." keeps this state in a
// namespace of its own so copy/paste can strip it without touching any other
// studio.* extension (see studioio::append).
inline const char* digestKey() { return "studio.nameLink.digest"; }
inline const char* refsKey() { return "studio.nameLink.refs"; }
inline const char* groupLabel() { return "命名结构"; }
inline const char* staleMessage() { return "结构已经发生变动"; }
inline bool isLinkKey(const std::string& key) { return key.compare(0, 16, "studio.nameLink.") == 0; }

inline bool aliveRef(const Document& doc, const ObjectRef& ref) {
    switch (ref.kind) {
    case ObjectKind::Atom: return doc.atoms().alive(ref.id) != 0;
    case ObjectKind::Bond: return doc.bonds().alive(ref.id) != 0;
    case ObjectKind::Text: return doc.texts().alive(ref.id) != 0;
    case ObjectKind::Path: return doc.paths().alive(ref.id) != 0;
    case ObjectKind::Table: return doc.tables().alive(ref.id) != 0;
    case ObjectKind::Group: return doc.groups().alive(ref.id) != 0;
    case ObjectKind::Arrow: return doc.arrows().alive(ref.id) != 0;
    case ObjectKind::Bracket: return doc.brackets().alive(ref.id) != 0;
    case ObjectKind::Orbital: return doc.orbitals().alive(ref.id) != 0;
    case ObjectKind::Symbol: return doc.symbols().alive(ref.id) != 0;
    case ObjectKind::BioShape: return doc.bioShapes().alive(ref.id) != 0;
    default: return false;
    }
}

inline char kindLetter(ObjectKind kind) {
    switch (kind) {
    case ObjectKind::Atom: return 'a';
    case ObjectKind::Bond: return 'b';
    case ObjectKind::Text: return 't';
    case ObjectKind::Path: return 'p';
    case ObjectKind::Table: return 'x';
    case ObjectKind::Group: return 'g';
    case ObjectKind::Arrow: return 'r';
    case ObjectKind::Bracket: return 'k';
    case ObjectKind::Orbital: return 'o';
    case ObjectKind::Symbol: return 's';
    case ObjectKind::BioShape: return 'i';
    default: return '?';
    }
}

inline bool letterKind(char letter, ObjectKind* out) {
    switch (letter) {
    case 'a': *out = ObjectKind::Atom; return true;
    case 'b': *out = ObjectKind::Bond; return true;
    case 't': *out = ObjectKind::Text; return true;
    case 'p': *out = ObjectKind::Path; return true;
    case 'x': *out = ObjectKind::Table; return true;
    case 'g': *out = ObjectKind::Group; return true;
    case 'r': *out = ObjectKind::Arrow; return true;
    case 'k': *out = ObjectKind::Bracket; return true;
    case 'o': *out = ObjectKind::Orbital; return true;
    case 's': *out = ObjectKind::Symbol; return true;
    case 'i': *out = ObjectKind::BioShape; return true;
    default: return false;
    }
}

// "a12,b3,t9" - deterministic because refs are sorted.
inline std::string encodeRefs(const std::vector<ObjectRef>& refs) {
    std::vector<ObjectRef> sorted(refs.begin(), refs.end());
    std::sort(sorted.begin(), sorted.end());
    sorted.erase(std::unique(sorted.begin(), sorted.end()), sorted.end());
    std::string out;
    for (size_t i = 0; i < sorted.size(); ++i) {
        if (i) out += ',';
        out += kindLetter(sorted[i].kind);
        out += std::to_string(static_cast<unsigned long long>(sorted[i].id));
    }
    return out;
}

inline std::vector<ObjectRef> decodeRefs(const std::string& text) {
    std::vector<ObjectRef> refs;
    size_t start = 0;
    while (start <= text.size()) {
        const size_t comma = text.find(',', start);
        const std::string token = text.substr(start, comma == std::string::npos ? std::string::npos : comma - start);
        if (token.size() >= 2) {
            ObjectKind kind = ObjectKind::Unknown;
            if (letterKind(token[0], &kind)) {
                const unsigned long long id = std::strtoull(token.c_str() + 1, 0, 10);
                refs.push_back(ObjectRef(kind, static_cast<ObjectId>(id)));
            }
        }
        if (comma == std::string::npos) break;
        start = comma + 1;
    }
    return refs;
}

inline uint64_t fnv(uint64_t hash, const std::string& text) {
    for (size_t i = 0; i < text.size(); ++i) {
        hash ^= static_cast<unsigned char>(text[i]);
        hash *= 1099511628211ull;
    }
    return hash;
}

// Relative positions are quantised to 1/10 pt so a group translation (which
// adds the same delta to every coordinate) cannot flip a tick through floating
// point noise, while a real edit does.
inline long long positionTick(double value, double origin) {
    const double delta = (value - origin) * 10.0;
    return static_cast<long long>(delta >= 0 ? delta + 0.5 : delta - 0.5);
}

inline std::string atomIdentityToken(const Document& doc, const AtomRecord& atom) {
    std::string token;
    token += std::to_string(int(atom.element)); token += '|';
    token += std::to_string(int(atom.semantics.charge)); token += '|';
    token += std::to_string(int(atom.semantics.isotope)); token += '|';
    token += std::to_string(int(atom.semantics.implicitHydrogens)); token += '|';
    token += std::to_string(int(atom.semantics.radical)); token += '|';
    token += std::to_string(int(atom.semantics.nodeType)); token += '|';
    token += std::to_string(int(atom.semantics.showLabel)); token += '|';
    token += std::to_string(int(atom.semantics.aromatic)); token += '|';
    token += doc.atomLabel(atom.id);
    return token;
}

inline std::string atomToken(const Document& doc, const AtomRecord& atom, double cx, double cy) {
    std::string token = atomIdentityToken(doc, atom);
    token += '|';
    token += std::to_string(positionTick(atom.position.x, cx)); token += ',';
    token += std::to_string(positionTick(atom.position.y, cy));
    return token;
}

// A digest of the linked structure. Only atoms reachable from the linked refs
// are described; the caption text itself is never part of it. The digest is
// independent of ObjectId numbering (tokens are sorted), so it survives the
// CDXML round-trip where ids are regenerated.
inline uint64_t structureDigest(const Document& doc, const std::vector<ObjectRef>& refs) {
    std::set<ObjectId> atoms;
    for (size_t i = 0; i < refs.size(); ++i) {
        if (refs[i].kind == ObjectKind::Atom && doc.atoms().alive(refs[i].id)) atoms.insert(refs[i].id);
        else if (refs[i].kind == ObjectKind::Bond) {
            const BondRecord* bond = doc.bonds().alive(refs[i].id);
            if (bond) { atoms.insert(bond->beginAtom); atoms.insert(bond->endAtom); }
        }
    }
    double cx = 0, cy = 0;
    size_t count = 0;
    for (std::set<ObjectId>::const_iterator it = atoms.begin(); it != atoms.end(); ++it) {
        const AtomRecord* atom = doc.atoms().alive(*it);
        if (!atom) continue;
        cx += atom->position.x; cy += atom->position.y; ++count;
    }
    if (count) { cx /= double(count); cy /= double(count); }
    std::vector<std::string> tokens;
    tokens.push_back("atoms:" + std::to_string(static_cast<unsigned long long>(count)));
    std::map<ObjectId, std::string> byId;
    for (std::set<ObjectId>::const_iterator it = atoms.begin(); it != atoms.end(); ++it) {
        const AtomRecord* atom = doc.atoms().alive(*it);
        if (!atom) continue;
        byId[*it] = atomToken(doc, *atom, cx, cy);
        tokens.push_back("a:" + byId[*it]);
    }
    size_t bonds = 0;
    for (const auto& bond : doc.bonds().records()) {
        if (!bond.isAlive()) continue;
        const bool beginInside = atoms.count(bond.beginAtom) != 0;
        const bool endInside = atoms.count(bond.endAtom) != 0;
        if (!beginInside && !endInside) continue;
        if (!doc.atoms().alive(bond.beginAtom) || !doc.atoms().alive(bond.endAtom)) continue;
        // An outside atom contributes only its identity: its coordinates are not
        // linked state, and only the fact that a substituent was attached matters.
        std::string begin = beginInside ? byId[bond.beginAtom] : atomIdentityToken(doc, *doc.atoms().alive(bond.beginAtom));
        std::string end = endInside ? byId[bond.endAtom] : atomIdentityToken(doc, *doc.atoms().alive(bond.endAtom));
        if (!beginInside) std::swap(begin, end); // inside endpoint first keeps the token canonical
        std::string token;
        token += std::to_string(int(bond.order)); token += '|';
        token += std::to_string(int(bond.display)); token += '|';
        token += std::to_string(int(bond.semantics)); token += '|';
        token += std::to_string(int(bond.stereo)); token += '|';
        token += begin; token += '>'; token += end;
        tokens.push_back("b:" + token);
        ++bonds;
    }
    tokens.push_back("bonds:" + std::to_string(static_cast<unsigned long long>(bonds)));
    std::sort(tokens.begin(), tokens.end());
    uint64_t hash = 1469598103934665603ull;
    for (size_t i = 0; i < tokens.size(); ++i) { hash = fnv(hash, tokens[i]); hash = fnv(hash, "\n"); }
    return hash;
}

// Stable structure digest, spelled as the decimal string stored on the caption.
inline std::string structureDigestText(const Document& doc, const std::vector<ObjectRef>& refs) {
    return std::to_string(static_cast<unsigned long long>(structureDigest(doc, refs)));
}

inline bool hasLink(const Document& doc, ObjectId textId) {
    const ExtensionBag& bag = doc.extensions(ObjectRef(ObjectKind::Text, textId));
    return bag.findValue(digestKey()) != 0;
}

inline bool stale(const Document& doc, ObjectId textId) {
    const ExtensionBag& bag = doc.extensions(ObjectRef(ObjectKind::Text, textId));
    if (!doc.texts().alive(textId)) return false;
    const std::string* digest = bag.findValue(digestKey());
    if (!digest) return false;
    const std::string* refsText = bag.findValue(refsKey());
    if (!refsText) return true;
    const std::vector<ObjectRef> refs = decodeRefs(*refsText);
    if (refs.empty()) return true;
    // Any linked object that vanished is itself a structural change.
    for (size_t i = 0; i < refs.size(); ++i) if (!aliveRef(doc, refs[i])) return true;
    return structureDigestText(doc, refs) != *digest;
}

inline std::vector<ObjectId> staleTexts(const Document& doc) {
    std::vector<ObjectId> out;
    for (const auto& text : doc.texts().records())
        if (text.isAlive() && stale(doc, text.id)) out.push_back(text.id);
    return out;
}

inline std::vector<ObjectRef> linkRefs(const Document& doc, ObjectId textId) {
    const ExtensionBag& bag = doc.extensions(ObjectRef(ObjectKind::Text, textId));
    const std::string* refsText = bag.findValue(refsKey());
    return refsText ? decodeRefs(*refsText) : std::vector<ObjectRef>();
}

// The top-most group owning a ref, or the ref itself when it is ungrouped.
// Auto-grouping a caption with a structure that is already inside a user group
// nests that user group instead of stealing its members.
inline ObjectRef topOwner(const Document& doc, const ObjectRef& ref) {
    ObjectRef current = ref;
    for (int guard = 0; guard < 512; ++guard) {
        ObjectRef parent;
        for (const auto& group : doc.groups().records()) {
            if (!group.isAlive()) continue;
            if (std::find(group.members.begin(), group.members.end(), current) != group.members.end()) {
                parent = ObjectRef(ObjectKind::Group, group.id);
                break;
            }
        }
        if (!parent.valid()) return current;
        current = parent;
    }
    return current;
}

inline std::vector<ObjectRef> topLevelMembers(const Document& doc, const std::vector<ObjectRef>& refs) {
    std::set<ObjectRef> unique;
    for (size_t i = 0; i < refs.size(); ++i) {
        if (!aliveRef(doc, refs[i])) continue;
        unique.insert(topOwner(doc, refs[i]));
    }
    return std::vector<ObjectRef>(unique.begin(), unique.end());
}

inline ObjectId owningGroup(const Document& doc, const ObjectRef& ref) {
    const ObjectRef owner = topOwner(doc, ref);
    return owner.kind == ObjectKind::Group ? owner.id : kInvalidObjectId;
}

// Every caption already linked to any of the given structure refs. Used by
// 结构转命名 to REPLACE its previous caption instead of stacking a second one.
inline std::vector<ObjectId> linkedTextsForStructure(const Document& doc, const std::vector<ObjectRef>& refs) {
    std::set<ObjectRef> wanted(refs.begin(), refs.end());
    std::vector<ObjectId> out;
    for (const auto& text : doc.texts().records()) {
        if (!text.isAlive()) continue;
        const std::vector<ObjectRef> linked = linkRefs(doc, text.id);
        if (linked.empty()) continue;
        bool shared = false;
        for (size_t i = 0; i < linked.size() && !shared; ++i) shared = wanted.count(linked[i]) != 0;
        if (shared) out.push_back(text.id);
    }
    return out;
}

inline void setLink(Document& doc, ObjectId textId, const std::vector<ObjectRef>& refs, const std::string& digest) {
    ExtensionBag& bag = doc.extensions(ObjectRef(ObjectKind::Text, textId));
    bag.set(digestKey(), digest);
    bag.set(refsKey(), encodeRefs(refs));
    doc.noteTouchedExtensions(ObjectRef(ObjectKind::Text, textId), false);
}

inline void clearLink(Document& doc, ObjectId textId) {
    ExtensionBag& bag = doc.extensions(ObjectRef(ObjectKind::Text, textId));
    const bool had = bag.findValue(digestKey()) || bag.findValue(refsKey());
    bag.erase(digestKey());
    bag.erase(refsKey());
    if (had) doc.noteTouchedExtensions(ObjectRef(ObjectKind::Text, textId), false);
}

} // namespace namelink

#endif // STUDIO_ENGINE_NAME_LINK_HPP
